#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
bool running = false;
bool ledOn = false;
int previousRaw = HIGH;
int stableButton = HIGH;
unsigned long changedAt = 0;
unsigned long toggledAt = 0;
int displayedPeriod = -1;

void setup() {
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  pinMode(2, INPUT_PULLUP);
  display.setBrightness(7);
}

void loop() {
  unsigned long now = millis();
  unsigned long period = 200UL + (unsigned long)analogRead(A0) * 1800UL / 1023UL;
  if ((int)period != displayedPeriod) {
    display.showNumberDec((int)period, false);
    displayedPeriod = (int)period;
  }

  int raw = digitalRead(2);
  if (raw != previousRaw) {
    previousRaw = raw;
    changedAt = now;
  }
  if (raw != stableButton && now - changedAt >= 30UL) {
    stableButton = raw;
    if (stableButton == LOW) {
      running = !running;
      ledOn = running;
      digitalWrite(13, ledOn ? HIGH : LOW);
      toggledAt = now;
    }
  }

  if (running && now - toggledAt >= period / 2UL) {
    toggledAt = now;
    ledOn = !ledOn;
    digitalWrite(13, ledOn ? HIGH : LOW);
  }
}
